<?php $this->layout('default'); use Moves\Services\CmsAuth; use Moves\Services\PlatformBilling as B; use Moves\Support\CmsView as V; $rows = B::plans(['q' => V::queryString('q')]); ?>
<div class="cms-card"><form class="cms-filters" method="get"><?= V::field('Pesquisar', 'q', V::queryString('q'), ['type' => 'search']) ?><button class="cms-btn">Filtrar</button><?php if (CmsAuth::can($admin, 'plans.manage')): ?><a class="cms-btn-primary" href="/planos/novo">Novo plano</a><?php endif; ?></form>
<?php if ($rows === []): ?><?= V::empty('Nenhum plano cadastrado.', 'O site só mostra planos ativos, públicos e com preço.') ?><?php else: ?><div class="cms-table-wrap" tabindex="0" role="region" aria-label="Planos"><table><thead><tr><th>Plano</th><th class="num">Mensal</th><th class="num">Anual</th><th>Situação</th><th>Site</th><th class="num">Assinantes</th></tr></thead><tbody><?php foreach ($rows as $p): ?><tr><td><a href="/planos/<?= (int) $p['id'] ?>"><?= V::e($p['name']) ?></a><?= $p['is_featured'] ? ' ' . V::badge('active', 'Destaque') : '' ?></td><td class="num"><?= V::money($p['monthly_price']) ?></td><td class="num"><?= V::money($p['annual_price']) ?></td><td><?= V::badge($p['status'], $p['status'] === 'active' ? 'Ativo' : 'Inativo') ?></td><td><?= $p['is_public'] ? 'Público' : 'Oculto' ?></td><td class="num"><?= (int) $p['subscribers'] ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></div>
